use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = json!([]);
    let mut pairs = input.as_array().unwrap().iter();
    let mut sorted_pairs = Vec::new();

    while let Some(pair) = pairs.next() {
        let priority = pair[0];
        let id = pair[1];

        sorted_pairs.push((priority, id));
    }

    sorted_pairs.sort_by(|(p1, _), (p2, _)| p2.cmp(p1));

    for (priority, id) in sorted_pairs {
        result = json!([result, json!(id)]);
    }

    result
}
